240: /* Server and client packet out is identical */
241: int send_packets_out(void *ctx, const struct lsquic_out_spec *specs, unsigned n_specs) {
242: #ifndef _WIN32
243:     us_quic_socket_context_t *context = ctx;
244: 
245:     /* A run is at most UIO_MAXIOV datagrams long */
246:     struct mmsghdr hdrs[UIO_MAXIOV];
247:     int run_length = 0;
248: 
249:     /* We assume that thiss whole cb will never be called with 0 specs */
250:     struct us_udp_socket_t *last_socket = (struct us_udp_socket_t *) specs[0].peer_ctx;
251: 
252:     int sent = 0;
253:     for (int i = 0; i < n_specs; i++) {
254:         /* Send this run if we need to */
255:         if (run_length == UIO_MAXIOV || specs[i].peer_ctx != last_socket) {
256:             int ret = bsd_sendmmsg(us_poll_fd((struct us_poll_t *) last_socket), hdrs, run_length, 0);
257:             if (ret != run_length) {
258:                 if (ret == -1) {
259:                     printf("unhandled udp backpressure!\n");
260:                     return sent;
261:                 } else {
262:                     printf("unhandled udp backpressure!\n");
263:                     errno = EAGAIN;
264:                     return sent + ret;
265:                 }
266:             }
267:             sent += ret;
268:             run_length = 0;
269:             last_socket = specs[i].peer_ctx;
270:             //printf("different socket breask run!\n");
271:         }
272: 
273:         /* Continue existing run or start a new one */
274:         //memset(&hdrs[i].msg_hdr, 0, sizeof(hdrs[i].msg_hdr));
275:         memset(&hdrs[run_length], 0, sizeof(hdrs[run_length]));
276: 
277:         hdrs[run_length].msg_hdr.msg_name       = (void *) specs[i].dest_sa;
278:         hdrs[run_length].msg_hdr.msg_namelen    = (AF_INET == specs[i].dest_sa->sa_family ?
279:                                             sizeof(struct sockaddr_in) :
280:                                             sizeof(struct sockaddr_in6)),
281:         hdrs[run_length].msg_hdr.msg_iov        = specs[i].iov;
282:         hdrs[run_length].msg_hdr.msg_iovlen     = specs[i].iovlen;
283:         hdrs[run_length].msg_hdr.msg_flags      = 0;
284: 
285:         run_length++;
286:     }
287: 
288:     /* Send last run */
289:     if (run_length) {
290:         int ret = bsd_sendmmsg(us_poll_fd((struct us_poll_t *) last_socket), hdrs, run_length, 0);
291:         if (ret == -1) {
292:             printf("backpressure! A\n");
293:             return sent;
294:         }
295:         if (sent + ret != n_specs) {
296:             printf("backpressure! B\n");
297:             printf("errno is: %d\n", errno);
298:             errno = EAGAIN;
299:         }
300:         //printf("Returning %d of %d\n", sent + ret, n_specs);
301:         return sent + ret;
302:     }
303: 
304:     //printf("Returning %d\n", n_specs);
305: 
306: #endif
307: 
308:     return n_specs;
309: }
