589: /* Returns NULL or SSL_CTX. May call missing server name callback */
590: SSL_CTX *resolve_context(struct us_internal_ssl_socket_context_t *context, const char *hostname) {
591: 
592:     /* Try once first */
593:     void *user = sni_find(context->sni, hostname);
594:     if (!user) {
595:         /* Emit missing hostname then try again */
596:         if (!context->on_server_name) {
597:             /* We have no callback registered, so fail */
598:             return NULL;
599:         }
600: 
601:         context->on_server_name(context, hostname);
602: 
603:         /* Last try */
604:         user = sni_find(context->sni, hostname);
605:     }
606: 
607:     return user;
608: }
