610: // arg is context
611: int sni_cb(SSL *ssl, int *al, void *arg) {
612: 
613:     if (ssl) {
614:         const char *hostname = SSL_get_servername(ssl, TLSEXT_NAMETYPE_host_name);
615:         if (hostname && hostname[0]) {
616:             /* Try and resolve (match) required hostname with what we have registered */
617:             SSL_CTX *resolved_ssl_context = resolve_context((struct us_internal_ssl_socket_context_t *) arg, hostname);
618:             if (resolved_ssl_context) {
619:                 //printf("Did find matching SNI context for hostname: <%s>!\n", hostname);
620:                 SSL_set_SSL_CTX(ssl, resolved_ssl_context);
621:             } else {
622:                 /* Call a blocking callback notifying of missing context */
623:             }
624: 
625:         }
626: 
627:         return SSL_TLSEXT_ERR_OK;
628:     }
629: 
630:     /* Can we even come here ever? */
631:     return SSL_TLSEXT_ERR_NOACK;
632: }
