634: struct us_internal_ssl_socket_context_t *us_internal_create_ssl_socket_context(struct us_loop_t *loop, int context_ext_size, struct us_socket_context_options_t options) {
635:     /* If we haven't initialized the loop data yet, do so .
636:      * This is needed because loop data holds shared OpenSSL data and
637:      * the function is also responsible for initializing OpenSSL */
638:     us_internal_init_loop_ssl_data(loop);
639: 
640:     /* First of all we try and create the SSL context from options */
641:     SSL_CTX *ssl_context = create_ssl_context_from_options(options);
642:     if (!ssl_context) {
643:         /* We simply fail early if we cannot even create the OpenSSL context */
644:         return NULL;
645:     }
646: 
647:     /* Otherwise ee continue by creating a non-SSL context, but with larger ext to hold our SSL stuff */
648:     struct us_internal_ssl_socket_context_t *context = (struct us_internal_ssl_socket_context_t *) us_create_socket_context(0, loop, sizeof(struct us_internal_ssl_socket_context_t) - sizeof(struct us_socket_context_t) + context_ext_size, options);
649: 
650:     /* I guess this is the only optional callback */
651:     context->on_server_name = NULL;
652: 
653:     /* Then we extend its SSL parts */
654:     context->ssl_context = ssl_context;//create_ssl_context_from_options(options);
655:     context->is_parent = 1;
656: 
657:     /* We, as parent context, may ignore data */
658:     context->sc.is_low_prio = (int (*)(struct us_socket_t *)) ssl_is_low_prio;
659: 
660:     /* Parent contexts may use SNI */
661:     SSL_CTX_set_tlsext_servername_callback(context->ssl_context, sni_cb);
662:     SSL_CTX_set_tlsext_servername_arg(context->ssl_context, context);
663: 
664:     /* Also create the SNI tree */
665:     context->sni = sni_new();
666: 
667:     return context;
668: }
