    /* It is program error to release suspended filters */
    us_poll_change(p, loop, LIBUS_SOCKET_READABLE | LIBUS_SOCKET_WRITABLE);
    dispatch_release(p->gcd_read);
    dispatch_release(p->gcd_write);
